import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { projectsAPI, contractsAPI } from '../services/api';
import toast from 'react-hot-toast';

function Sidebar({ active }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const links = [
    { id: 'dashboard', label: 'Tableau de bord', icon: '📊', path: '/dashboard' },
    { id: 'projects', label: 'Projets', icon: '🏗️', path: '/projects' },
    { id: 'contracts', label: 'Contrats', icon: '📄', path: '/contracts' },
  ];

  return (
    <aside style={{
      width: 260, minHeight: '100vh',
      background: 'var(--dark-2)',
      borderRight: '1px solid var(--dark-border)',
      display: 'flex', flexDirection: 'column',
      padding: '28px 0',
      position: 'fixed', left: 0, top: 0,
      zIndex: 100,
    }}>
      {/* Logo */}
      <div style={{ padding: '0 24px 32px', borderBottom: '1px solid var(--dark-border)' }}>
        <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{ width: 34, height: 34, background: 'var(--gold)', borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#1A1A2E" strokeWidth="2.5">
              <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/>
              <polyline points="9 22 9 12 15 12 15 22"/>
            </svg>
          </div>
          <span style={{ fontFamily: 'var(--font-display)', fontWeight: 800, fontSize: 18 }}>
            Chantier<span style={{ color: 'var(--gold)' }}>360</span>
          </span>
        </Link>
      </div>

      {/* Nav */}
      <nav style={{ flex: 1, padding: '20px 12px', display: 'flex', flexDirection: 'column', gap: 4 }}>
        {links.map(l => (
          <Link key={l.id} to={l.path} style={{
            display: 'flex', alignItems: 'center', gap: 12,
            padding: '12px 16px', borderRadius: 'var(--radius)',
            background: active === l.id ? 'rgba(245,158,11,0.12)' : 'transparent',
            color: active === l.id ? 'var(--gold)' : 'var(--gray-3)',
            fontSize: 14, fontWeight: active === l.id ? 600 : 400,
            transition: 'all 0.2s',
            borderLeft: active === l.id ? '3px solid var(--gold)' : '3px solid transparent',
          }}>
            <span>{l.icon}</span> {l.label}
          </Link>
        ))}
      </nav>

      {/* User */}
      <div style={{ padding: '20px 24px', borderTop: '1px solid var(--dark-border)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
          <div style={{
            width: 38, height: 38, borderRadius: '50%',
            background: 'var(--gold)', display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontFamily: 'var(--font-display)', fontWeight: 800, color: 'var(--dark)', fontSize: 16,
          }}>
            {user?.full_name?.charAt(0)?.toUpperCase()}
          </div>
          <div style={{ flex: 1, overflow: 'hidden' }}>
            <div style={{ fontSize: 14, fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{user?.full_name}</div>
            <div style={{ fontSize: 12, color: 'var(--gray-4)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{user?.company_name}</div>
          </div>
        </div>
        <button onClick={() => { logout(); navigate('/login'); }}
          style={{ width: '100%', background: 'rgba(239,68,68,0.1)', color: '#EF4444', border: '1px solid rgba(239,68,68,0.2)', borderRadius: 'var(--radius-sm)', padding: '8px 12px', fontSize: 13, cursor: 'pointer', transition: 'all 0.2s' }}>
          Déconnexion
        </button>
      </div>
    </aside>
  );
}

export default function DashboardPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [projects, setProjects] = useState([]);
  const [contracts, setContracts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([projectsAPI.list(), contractsAPI.list()])
      .then(([pRes, cRes]) => { setProjects(pRes.data); setContracts(cRes.data); })
      .catch(() => toast.error('Erreur de chargement'))
      .finally(() => setLoading(false));
  }, []);

  const stats = [
    { label: 'Projets actifs', value: projects.filter(p => p.status === 'en_cours').length, icon: '🏗️', color: 'var(--gold)' },
    { label: 'Total projets', value: projects.length, icon: '📁', color: '#60A5FA' },
    { label: 'Contrats analysés', value: contracts.filter(c => c.status === 'completed').length, icon: '📄', color: '#10B981' },
    { label: 'En traitement', value: contracts.filter(c => c.status === 'processing').length, icon: '⏳', color: '#F59E0B' },
  ];

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: 'var(--dark)' }}>
      <Sidebar active="dashboard" />
      <main style={{ marginLeft: 260, flex: 1, padding: '40px 36px' }}>
        {/* Header */}
        <div className="animate-fade-in" style={{ marginBottom: 36 }}>
          <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 28, fontWeight: 800, marginBottom: 6 }}>
            Bonjour, {user?.full_name?.split(' ')[0]} 👋
          </h1>
          <p style={{ color: 'var(--gray-3)', fontSize: 15 }}>{user?.company_name} — Tableau de bord</p>
        </div>

        {/* Stats */}
        <div className="animate-fade-in delay-1" style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 20, marginBottom: 36 }}>
          {stats.map((s, i) => (
            <div key={i} className="card" style={{ padding: 20 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                <span style={{ fontSize: 24 }}>{s.icon}</span>
                <div style={{ width: 8, height: 8, borderRadius: '50%', background: s.color }} />
              </div>
              <div style={{ fontSize: 32, fontFamily: 'var(--font-display)', fontWeight: 800, color: s.color }}>{s.value}</div>
              <div style={{ fontSize: 13, color: 'var(--gray-3)', marginTop: 4 }}>{s.label}</div>
            </div>
          ))}
        </div>

        {/* Quick actions */}
        <div className="animate-fade-in delay-2" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 36 }}>
          <button onClick={() => navigate('/projects/new')} className="card" style={{
            cursor: 'pointer', textAlign: 'left', border: '1px dashed var(--dark-border)',
            background: 'transparent', transition: 'all 0.2s', display: 'flex', alignItems: 'center', gap: 16,
          }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = 'var(--gold)'; e.currentTarget.style.background = 'rgba(245,158,11,0.04)'; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--dark-border)'; e.currentTarget.style.background = 'transparent'; }}>
            <div style={{ width: 48, height: 48, background: 'rgba(245,158,11,0.15)', borderRadius: 'var(--radius)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22 }}>➕</div>
            <div>
              <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 16, marginBottom: 4 }}>Nouveau projet</div>
              <div style={{ fontSize: 13, color: 'var(--gray-3)' }}>Créer et gérer un nouveau chantier</div>
            </div>
          </button>

          <button onClick={() => navigate('/contracts/upload')} className="card" style={{
            cursor: 'pointer', textAlign: 'left', border: '1px dashed var(--dark-border)',
            background: 'transparent', transition: 'all 0.2s', display: 'flex', alignItems: 'center', gap: 16,
          }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = '#60A5FA'; e.currentTarget.style.background = 'rgba(96,165,250,0.04)'; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--dark-border)'; e.currentTarget.style.background = 'transparent'; }}>
            <div style={{ width: 48, height: 48, background: 'rgba(96,165,250,0.15)', borderRadius: 'var(--radius)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22 }}>📄</div>
            <div>
              <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 16, marginBottom: 4 }}>Analyser un contrat</div>
              <div style={{ fontSize: 13, color: 'var(--gray-3)' }}>Upload PDF ou Word — résumé IA instantané</div>
            </div>
          </button>
        </div>

        {/* Recent projects */}
        <div className="animate-fade-in delay-3">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
            <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 20, fontWeight: 700 }}>Projets récents</h2>
            <Link to="/projects" style={{ fontSize: 13, color: 'var(--gold)' }}>Voir tous →</Link>
          </div>

          {loading ? (
            <div style={{ textAlign: 'center', padding: 40, color: 'var(--gray-3)' }}>Chargement...</div>
          ) : projects.length === 0 ? (
            <div className="card" style={{ textAlign: 'center', padding: 48 }}>
              <div style={{ fontSize: 48, marginBottom: 16 }}>🏗️</div>
              <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 18, marginBottom: 8 }}>Aucun projet pour l'instant</h3>
              <p style={{ color: 'var(--gray-3)', fontSize: 14, marginBottom: 20 }}>Créez votre premier projet BTP</p>
              <button className="btn-primary" style={{ width: 'auto', padding: '10px 24px' }} onClick={() => navigate('/projects/new')}>
                Créer un projet
              </button>
            </div>
          ) : (
            <div style={{ display: 'grid', gap: 12 }}>
              {projects.slice(0, 5).map(p => (
                <div key={p.id} className="card" style={{ padding: '16px 20px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', cursor: 'pointer', transition: 'border-color 0.2s' }}
                  onClick={() => navigate(`/projects/${p.id}`)}
                  onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--gold)'}
                  onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--dark-border)'}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
                    <div style={{ width: 40, height: 40, background: 'rgba(245,158,11,0.12)', borderRadius: 'var(--radius-sm)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18 }}>
                      {p.project_type === 'batiment' ? '🏢' : p.project_type === 'route' ? '🛣️' : p.project_type === 'aep' ? '💧' : '🏗️'}
                    </div>
                    <div>
                      <div style={{ fontWeight: 600, fontSize: 14, marginBottom: 2 }}>{p.name}</div>
                      <div style={{ fontSize: 12, color: 'var(--gray-3)' }}>{p.location || 'Localisation non définie'} · {p.contracts_count} contrat(s)</div>
                    </div>
                  </div>
                  <span className={`badge badge-${p.status === 'en_cours' ? 'success' : p.status === 'termine' ? 'gray' : 'gold'}`}>
                    {p.status === 'en_cours' ? 'En cours' : p.status === 'termine' ? 'Terminé' : p.status === 'planifie' ? 'Planifié' : 'Suspendu'}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

export { Sidebar };
